const item = $input.item;
const articulo = $('Cola de Artículos').item.json;
const PRODUCTOS = articulo.PRODUCTOS;
const prod = PRODUCTOS[articulo.producto];

// Contenido generado por IA
const contenidoIA = item.json.message?.content || item.json.choices?.[0]?.message?.content || '';

// Color según cluster
const colores = {
  'snack-barf':     { grad: '135deg,#1a7a4a 0%,#2ecc71 100%', text: '#1a7a4a', bg: '#f0faf4' },
  'dieta-natural':  { grad: '135deg,#1a7a4a 0%,#2ecc71 100%', text: '#1a7a4a', bg: '#f0faf4' },
  'vital-pet':      { grad: '135deg,#1a7a4a 0%,#27ae60 100%', text: '#1a7a4a', bg: '#f0faf4' },
  'calculadora':    { grad: '135deg,#1a7a4a 0%,#27ae60 100%', text: '#1a7a4a', bg: '#f0faf4' },
  'adiestramiento': { grad: '135deg,#1a5276 0%,#2980b9 100%', text: '#1a5276', bg: '#eaf4fb' },
  'mascotas-sanas': { grad: '135deg,#1a5276 0%,#2980b9 100%', text: '#1a5276', bg: '#eaf4fb' },
  'entiende-gato':  { grad: '135deg,#6c3483 0%,#a569bd 100%', text: '#6c3483', bg: '#f9f0ff' }
};

const c = colores[articulo.producto] || colores['mascotas-sanas'];

const breadcrumb = `
<div style="background:${c.bg};border-left:4px solid ${c.text};border-radius:8px;padding:12px 16px;margin:0 0 28px;font-family:Arial,sans-serif">
  <p style="margin:0;font-size:13px;color:#666">Parte de la guía completa:</p>
  <a href="${articulo.pillarUrl}" style="color:${c.text};font-weight:700;font-size:14px;text-decoration:none">→ ${articulo.pillarTitulo}</a>
</div>`;

const banner = `
<!-- BANNER HOTMART -->
<div style="background:linear-gradient(${c.grad});border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.imagen}" alt="${prod.nombre}" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} recomendado</p>
      <h3 style="color:#fff;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored" style="display:inline-block;background:#fff;color:${c.text};font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">
        Ver ahora →
      </a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.3);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado</p>
</div>`;

const htmlFinal = breadcrumb + contenidoIA + banner;

return [{
  json: {
    blogId: articulo.blogId,
    titulo: articulo.titulo,
    labels: articulo.labels,
    slug: articulo.slug,
    contenido: htmlFinal,
    isDraft: false
  }
}];

const post = $input.item.json;
console.log(`✅ Publicado: ${post.title} → ${post.url}`);
return [{ json: { titulo: post.title, url: post.url, id: post.id, publicado: new Date().toISOString() } }];
